using System.Collections.Immutable;
using Mist.Application.Commands;
using Mist.Application.Contracts;
using Mist.Application.Roster;
using Mist.Application.Storage;
using Mist.Core.ChapterSix;
using Mist.Core.Quests;

namespace Mist.Application.ChapterSix;
public sealed partial class ChapterSixService
{
    public async ValueTask<CommandResult> DecideTessInvitationAsync(string decision,bool recruit)
    {var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);At(s,"R6-S02.tess");Require(Closed(s,"Q-601")&&decision is "accept" or "defer" or "decline","正式邀请在测站闭合以后；可保持联系或暂缓。");Require(!recruit||decision=="accept"&&!Closed(s,"Q-603"),"正式同行在Q601后、Q603前，个人内容和主线资格分开。");var st=State(s);var changes=ImmutableArray.CreateBuilder<EntityChange>();changes.Add(Change(s,st with{TessInvitation=decision}));if(decision=="accept"&&Quest(s,"CQ-TESS-01") is{Lifecycle:QuestLifecycle.Unaccepted} cq)changes.Add(BranchOperations.Change(s,"quest:CQ-TESS-01","quest",cq.Accept()));if(recruit){var old=BranchOperations.Read<RosterEntry>(s,"roster:CP-TESS")??new("CP-TESS",Membership.Contact,ActorAvailability.LocalContact,"R6-S02",ImmutableDictionary<int,string>.Empty);Require(old.Availability is not(ActorAvailability.Working or ActorAvailability.Unavailable),"泰丝当前现场工作尚未交接。");changes.Add(BranchOperations.Change(s,"roster:CP-TESS","roster",old with{Membership=Membership.Joined,Availability=ActorAvailability.ShipStandby,Location="HUB-S01",LastDecision="accepted_actual_Q601_invitation"}));}return await Commit(s,"chapter_six_tess_invitation",changes.ToImmutable(),new{actor="CP-TESS",decision,recruit,source_quest="Q-601:resolution",no_main_permission_gate=true});}
    public async ValueTask<CommandResult> ConfirmTessContactsAsync(string shed,string ridge,string conditions)
    {var s=await _repository.SnapshotAsync();Safe(s);Editable(s);At(s,"R6-S05.contacts");Require(State(s).TessInvitation=="accept"&&Sources(s,"R6-CQTESS01-R-CONTACTS")&&shed=="ROLE-R6-SHED-RECEIVER"&&ridge=="ROLE-R6-RIDGE-RECEIVER"&&conditions=="complete_labels_same_current_manifest","须在本人当前邀请下核对两处真实现行接收岗与条件。");return await Commit(s,"chapter_six_tess_current_contacts",[Change(s,State(s) with{TessRecipients=true})],new{shed,ridge,conditions,source_manifest=Package.Version});}
    public async ValueTask<CommandResult> PlanSupplementAsync(string decision,ImmutableDictionary<string,int> trips)
    {var s=await _repository.SnapshotAsync();Safe(s);Editable(s);At(s,"R6-S05.supplement");var st=State(s);Require(Closed(s,"Q-601")&&Sources(s,"R6-Q603-R-LOAD")&&decision is "accept" or "decline","必须明确承接或拒绝这一独立可选补充。");Require(st.SupplementDelivered==0&&st.SupplementDecision!="accept","已承接货组需沿实际交付，不撤销复制或重留另一批。");if(decision=="accept"){Require(trips.Count==5&&SupplementSizes.Keys.All(trips.ContainsKey)&&trips.Values.All(n=>n is 1 or 2)&&Enumerable.Range(1,2).All(t=>trips.Where(k=>k.Value==t).Sum(k=>SupplementSizes[k.Key])<=6)&&trips["tools"]<trips["lighting"]&&trips["fittings"]<trips["lighting"],"整箱、两趟六格和工具安装件早于照明的条件不符；两种合法安排均接受。");}else Require(trips.Count==0,"拒绝运输不能同时留下已到货分配。");return await Commit(s,"chapter_six_optional_supplement_plan",[Change(s,st with{SupplementDecision=decision,SupplementTrips=trips})],new{decision,trips,stock_scope="independent_optional_not_base_or_transition"});}
    public async ValueTask<CommandResult> DeliverSupplementTripAsync(int trip)
    {var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);At(s,"R6-S05.supplement");var st=State(s);Require(st.SupplementDecision=="accept"&&trip==st.SupplementDelivered+1&&trip is 1 or 2&&st.CargoDelivered&&HasResult(s,"ENC-R6-03")&&HasResult(s,"ENC-R6-04")&&st.RidgeSafe,"只有真实主线安全段和接收点已成立后，才执行本可选补充的下一运输段。");var items=st.SupplementTrips.Where(x=>x.Value==trip).Select(x=>{var i=s.Items.Single(i=>i.Id=="R6-supplement:"+x.Key&&i.OwnerKind=="warehouse"&&i.OwnerId=="R6-S05:supplement");return new ItemChange(i.Id,i.DefinitionId,i.OwnerKind,i.OwnerId,"installed","R6:optional_settlement_supplement",null);}).ToImmutableArray();return await Commit(s,"chapter_six_optional_supplement_arrival",[Change(s,st with{SupplementDelivered=trip})],new{trip,actual_boxes=items.Select(i=>i.Id).ToArray(),qualified_commissioned_driver="ROLE-R6-CART-DRIVER",safe_route_receipts=new[]{"R6:ENC-R6-03:result","R6:ENC-R6-04:result"},receiving_scope="optional_settlement_supplement",parent_reward=0},"R6:supplement:trip:"+trip,items);}
    public async ValueTask<CommandResult> PrepareTessNoticeAsync(string first,string second,string record)
    {var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);At(s,"R6-S08.local_notice");Require(Closed(s,"CQ-TESS-02")&&State(s).TessInvitation=="accept"&&State(s).CargoDelivered&&Sources(s,"R6-CQTESS03-R-NOTICE")&&first=="ROLE-R6-NEXT-WATCH"&&second=="ROLE-R6-NOTICE-BACKUP"&&record=="current_delivery_sheet","必须保留原联系人，加入第二联系人并引用同一当前真实交付记录。");return await Commit(s,"chapter_six_tess_notice_prepared",[Change(s,State(s) with{TessMessage=true,TessSecondContact=true,TessReceivingConfirmed=false})],new{first,second,record,record_version=State(s).TowerRevision,main_delivery_present=true,protocol_signature=false});}
    public async ValueTask<CommandResult> SendTessNoticeAsync(long expectedDeliveryRevision)
    {var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);At(s,"R6-S08.local_notice");var st=State(s);Require(st.TessInvitation=="accept"&&st.TessMessage&&st.TessSecondContact&&st.CargoDelivered&&expectedDeliveryRevision==st.TowerRevision,"地方通知记录改变，请重新核对；不能发送过期收货表。");return await Commit(s,"chapter_six_local_notice_receiving_confirmed",[Change(s,st with{TessReceivingConfirmed=true})],new{actual_recipient="ROLE-R6-NEXT-WATCH",copy_recipient="ROLE-R6-NOTICE-BACKUP",receiving_record_version=expectedDeliveryRevision,confirmation="bounded_local_delivery_sheet_received",protocol_signature=false});}
}
